/**
 * Unit tests for AbstractCommandLineRunner#run().
 * Note: Since the method calls exit() and uses static PhaseOptimizer, 
 * we use Mockito's mockStatic to handle the static call and a spy to handle the exit() call.
 */
@RunWith(PowerMockRunner.class)
@PrepareForTest({PhaseOptimizer.class, AbstractCommandLineRunner.class})
public class AbstractCommandLineRunner_run_TriageGen0Test {

    @Mock
    private CommandLineConfig mockConfig;

    @Mock
    private RunTimeStats mockRunTimeStats;

    private AbstractCommandLineRunner runner;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // We spy on the runner to override the exit() method and doRun()
        runner = spy(new AbstractCommandLineRunner() {
            @Override
            protected CommandLineConfig getCommandLineConfig() { return mockConfig; }
            @Override
            protected Object createCompiler() { return null; }
            @Override
            protected Object createOptions() { return null; }
            @Override
            protected com.google.javascript.jscomp.DiagnosticGroups getDiagnosticGroups() { return null; }
            // Overriding exit to prevent actual JVM exit and to verify it
            @Override
            protected void exit(RunTimeStats stats, Throwable error) {
                // Do nothing
            }
            // Accessors for the fields in the runner via reflection or protected access if needed
            // For this test, we assume the fields are accessible or we mock the behavior
            public void setConfig(CommandLineConfig config) { this.config = config; }
            public void setRunTimeStats(RunTimeStats stats) { this.runTimeStats = stats; }

            // Expose fields that are likely private/protected in the real class
            private CommandLineConfig config;
            private RunTimeStats runTimeStats;
        });

        // Using reflection to inject mocks into the private/protected fields of the runner
        injectField(runner, "config", mockConfig);
        injectField(runner, "runTimeStats", mockRunTimeStats);
    }

    private void injectField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testRun_SingleRunSuccessNoPhaseOrdering() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        doReturn(1).when(runner).doRun();

        runner.run();

        verify(mockRunTimeStats, times(1)).recordStartRun();
        verify(mockRunTimeStats, times(1)).recordEndRun();
        verify(runner).exit(mockRunTimeStats, null);
    }

    @Test
    public void testRun_SingleRunSuccessWithPhaseOrdering() throws Exception {
        try (MockedStatic<PhaseOptimizer> phaseOptimizerMock = mockStatic(PhaseOptimizer.class)) {
            when(mockConfig.computePhaseOrdering).thenReturn(true);
            doReturn(1).when(runner).doRun();

            runner.run();

            phaseOptimizerMock.verify(PhaseOptimizer::randomizeLoops, times(1));
            verify(mockRunTimeStats, times(1)).recordStartRun();
            verify(runner).exit(mockRunTimeStats, null);
        }
    }

    @Test
    public void testRun_MultipleRunsUntilSuccess() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        // First run returns 0 (failure/continue), second run returns 1 (success/stop)
        doReturn(0).doReturn(1).when(runner).doRun();

        runner.run();

        verify(mockRunTimeStats, times(2)).recordStartRun();
        verify(mockRunTimeStats, times(2)).recordEndRun();
        verify(runner).exit(mockRunTimeStats, null);
    }

    @Test
    public void testRun_MultipleRunsExhausted() throws Exception {
        // In the original code, if runs = NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER, 
        // if all return 0, it stops after 'runs' iterations.
        // We assume NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER is a constant accessible.
        // For testing purposes, let's assume it's 3.

        // Since we can't easily change the constant NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER 
        // unless it's a field, we test the logic based on the config.

        when(mockConfig.computePhaseOrdering).thenReturn(true);
        doReturn(0).when(runner).doRun();

        // We need to know what NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER is. 
        // If we can't see it, we test that it runs at least once.
        runner.run();

        verify(mockRunTimeStats, atLeastOnce()).recordStartRun();
        verify(runner).exit(eq(mockRunTimeStats), any());
    }

    @Test
    public void testRun_ExceptionHandling() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        RuntimeException exception = new RuntimeException("Test Exception");
        doThrow(exception).when(runner).doRun();

        runner.run();

        verify(mockRunTimeStats, times(1)).recordStartRun();
        // recordEndRun is NOT called if exception occurs in doRun before it
        verify(mockRunTimeStats, never()).recordEndRun();
        verify(runner).exit(mockRunTimeStats, exception);
    }

    @Test
    public void testRun_ThrowableHandling() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        Error error = new Error("Fatal Error");
        doThrow(error).when(runner).doRun();

        runner.run();

        verify(runner).exit(mockRunTimeStats, error);
    }
}
